mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM comment c
    JOIN root r ON c.id = r.id
        AND r.type = 'COMMENT'
        AND 
    WHERE c.coeat_id = #{coeatId}
        AND c.id = #{commentId}
)

mapper.update:
UPDATE comment c
JOIN root r ON c.id = r.id
    AND r.type = 'COMMENT'
    AND 
SET c.content = #{comment.content},
    r.updated_at = NOW()
WHERE c.coeat_id = #{coeatId}
    AND c.user_id = #{userId}
    AND c.id = #{commentId}

UPDATE comment c
JOIN root r ON c.id = r.id
    AND r.type = 'COMMENT'
    AND 
SET r.deleted_at = NOW()
WHERE c.coeat_id = #{coeatId}
    AND c.user_id = #{userId}
    AND c.id = #{commentId}
